using System;
using System.Collections.Generic;
using System.Linq;
using NUnit.Framework;
using Polypiler.Core;
using Polypiler.Core.Backends.JavaScript;
using Polypiler.Core.IR;
using Polypiler.Prototype.Testing;

namespace Polypiler.Tests.Backends.JavaScript;

/// <summary>
/// The text the emitter writes for a profile. Whether that text computes the right thing is decided
/// by running it in node, in the acceptance tests; here every generated file is parsed at the level
/// it claims and searched for what its profile does not have.
/// </summary>
[TestFixture]
public sealed class JavaScriptProfileEmissionTests {

  private static readonly JavaScriptProfile _es5 = JavaScriptProfile.Parse("es5");
  private static readonly JavaScriptProfile _es5Typed = JavaScriptProfile.Parse("es5", typedArrays: true);
  private static readonly JavaScriptProfile _es2015 = JavaScriptProfile.Parse("es2015");
  private static readonly JavaScriptProfile _es2017 = JavaScriptProfile.Parse("es2017");
  private static readonly JavaScriptProfile _es2020 = JavaScriptProfile.Parse("es2020");

  /// <summary>Every valid combination of level, module format and, at ECMAScript 5, typed arrays.</summary>
  private static readonly JavaScriptProfile[] _profiles = [
    .. from level in JavaScriptProfile.LevelNames
       from module in JavaScriptProfile.ModuleNames
       where level != "es5" || module != "esm"
       from typed in level == "es5" ? new[] { false, true } : [false]
       select JavaScriptProfile.Parse(level, module, module == "iife" ? "Generated" : null, typed)
  ];

  /// <summary>Every fixture in every profile; the fixtures with hundreds of functions are in the slow tier.</summary>
  private static IEnumerable<TestCaseData> FixturesAndProfiles()
    => from fixture in PrototypeFixture.Names
       from profile in _profiles
       let data = new TestCaseData(fixture, profile).SetName($"{{m}}({fixture}, {profile})")
       select fixture is "wide/OperatorsWide" or "wide/Conversions" or "wide/Library" ? data.SetCategory("Slow") : data;

  private static IrModule Import(string methods) => PrototypeFixture.Import("Snippet.cs", PrototypeFixture.Wrap(methods));

  private static string Emit(string methods, JavaScriptProfile profile) {
    var module = JavaScriptEmitter.Legalize(Import(methods), () => Polypiler.Tests.Float.Support.FloatImplementations.Module, profile, FloatMode.Accurate);
    var text = JavaScriptEmitter.Emit(module, profile).Single().Content;
    Assert.That(GeneratedJavaScript.Problems(text, profile), Is.Empty, text);
    return text;
  }

  /// <summary>The body of the function <c>F</c>, one line per statement, without indentation.</summary>
  private static string[] Body(string methods, JavaScriptProfile profile) {
    var lines = Emit(methods, profile).Split('\n');
    var start = Array.FindIndex(lines, line => line.Contains("function F("));
    return lines.Skip(start + 1).TakeWhile(line => line != "}").Select(line => line.Trim()).ToArray();
  }

  /// <summary>The functions a module declares besides its own, in their order.</summary>
  private static string[] Helpers(string text)
    => text.Split('\n').Select(line => line.Trim()).Where(line => line.StartsWith("function $", StringComparison.Ordinal)).Select(line => line[10..line.IndexOf('(')]).ToArray();

  /// <summary>
  /// Test design 2: every fixture in every profile is one file named after its class and its module
  /// format, states its profile, and uses nothing its level lacks.
  /// </summary>
  [TestCaseSource(nameof(FixturesAndProfiles))]
  public void Fixture_IsAtTheLevelOfItsProfile(string fixture, JavaScriptProfile profile) {
    var module = PrototypeFixture.Imported(fixture);
    Assert.That(JavaScriptEmitter.Check(module, profile), Is.Empty);
    var files = JavaScriptEmitter.Emit(module, profile);
    Assert.That(files.Select(file => file.Path), Is.EqualTo(new[] { PrototypeFixture.ClassOf(fixture) + profile.Extension }));

    var text = files[0].Content;
    Assert.That(GeneratedJavaScript.Problems(text, profile), Is.Empty);
    Assert.That(text, Does.StartWith($"// {PrototypeFixture.ClassOf(fixture)}: generated by polypiler. Change the source, not this file.\n// JavaScript profile: {profile}.\n"));
    Assert.That(text, Does.EndWith("\n").And.Not.Contain("\r").And.Not.Contain("\t").And.Not.Contain("@"));
    if (profile.Level < JavaScriptLevel.Es2020)
      Assert.That(text, Does.Not.Contain("BigInt"));

    if (profile.Level < JavaScriptLevel.Es2015)
      Assert.That(text, Does.Not.Match(@"\b(let|const)\b").And.Not.Contain("Math.imul").And.Not.Contain("Math.fround").And.Not.Contain("Math.clz32").And.Not.Contain("Math.trunc").And.Not.Contain("Math.sign"));

    if (!profile.TypedArrays)
      Assert.That(text, Does.Not.Match(@"new \w+Array\(|DataView|ArrayBuffer"));
  }

  /// <summary>Test design 1: the profile of a command line that names none writes what the emitter always wrote.</summary>
  [TestCaseSource(typeof(PrototypeFixture), nameof(PrototypeFixture.Names))]
  public void DefaultProfile_IsTheOutputWithoutAProfile(string fixture) {
    var module = PrototypeFixture.Imported(fixture);
    var text = JavaScriptEmitter.Emit(module).Single().Content;
    Assert.That(JavaScriptEmitter.Emit(module, JavaScriptProfile.Default).Single(), Is.EqualTo(new GeneratedFile(PrototypeFixture.ClassOf(fixture) + ".mjs", text)));
    Assert.That(JavaScriptEmitter.Emit(module, JavaScriptProfile.Parse("es2022", "esm"), JavaScriptCapabilities.Standard).Single().Content, Is.EqualTo(text));
  }

  /// <summary>
  /// Nothing the emitter writes was added by ECMAScript 2016, 2017, 2021 or 2022: the levels in
  /// between differ in the line that states the profile and in nothing else.
  /// </summary>
  [TestCaseSource(typeof(PrototypeFixture), nameof(PrototypeFixture.Names))]
  public void NeighbouringLevels_DifferOnlyInTheirName(string fixture) {
    var module = PrototypeFixture.Imported(fixture);
    string Text(JavaScriptProfile profile) => JavaScriptEmitter.Emit(module, profile).Single().Content.Replace(profile.LevelName, "level");
    Assert.That(Text(_es2017), Is.EqualTo(Text(_es2015)));
    Assert.That(Text(JavaScriptProfile.Default), Is.EqualTo(Text(_es2020)));
  }

  /// <summary>The whole file of a CommonJS module: strict, the public functions as properties of exports.</summary>
  [Test]
  public void CommonJsModule_IsReadable() {
    var text = Emit(
      "public static uint Sum(byte[] data) { uint sum = 0; for (int i = 0; i < data.Length; ++i) sum += data[i]; return sum; } private static void Hidden() { } public static void Shown() { Hidden(); }",
      JavaScriptProfile.Parse("es2015", "cjs"));
    Assert.That(text, Is.EqualTo(string.Join('\n',
      "// Snippet: generated by polypiler. Change the source, not this file.",
      "// JavaScript profile: es2015, cjs.",
      "\"use strict\";",
      "",
      "function $get(array, index) {",
      "  if (index < 0 || index >= array.length) throw new RangeError(\"index out of range\");",
      "  return array[index];",
      "}",
      "",
      "// Sum(data: Uint8Array): number",
      "function Sum(data) {",
      "  let sum = 0;",
      "  {",
      "    let i = 0;",
      "    while (i < data.length) {",
      "      sum = (sum + $get(data, i)) >>> 0;",
      "      i = (i + 1) | 0;",
      "    }",
      "  }",
      "  return sum;",
      "}",
      "",
      "// Hidden(): void",
      "function Hidden() {",
      "}",
      "",
      "// Shown(): void",
      "function Shown() {",
      "  Hidden();",
      "}",
      "",
      "exports.Sum = Sum;",
      "exports.Shown = Shown;",
      "")));
  }

  /// <summary>The whole file of a script at ECMAScript 5: one global object built by a function that is called at once.</summary>
  [Test]
  public void Script_IsReadable() {
    var text = Emit(
      "public static uint Sum(byte[] data) { uint sum = 0; for (int i = 0; i < data.Length; ++i) sum += data[i]; return sum; } private static void Hidden() { } public static void Shown() { Hidden(); }",
      JavaScriptProfile.Parse("es5", "iife", "Checksums"));
    Assert.That(text, Is.EqualTo(string.Join('\n',
      "// Snippet: generated by polypiler. Change the source, not this file.",
      "// JavaScript profile: es5, iife as the global Checksums.",
      "var Checksums = (function () {",
      "  \"use strict\";",
      "",
      "  function $get(array, index) {",
      "    if (index < 0 || index >= array.length) throw new RangeError(\"index out of range\");",
      "    return array[index];",
      "  }",
      "",
      "  // Sum(data: Array<number>): number",
      "  function Sum(data) {",
      "    var sum = 0;",
      "    {",
      "      var i = 0;",
      "      while (i < data.length) {",
      "        sum = (sum + $get(data, i)) >>> 0;",
      "        i = (i + 1) | 0;",
      "      }",
      "    }",
      "    return sum;",
      "  }",
      "",
      "  // Hidden(): void",
      "  function Hidden() {",
      "  }",
      "",
      "  // Shown(): void",
      "  function Shown() {",
      "    Hidden();",
      "  }",
      "",
      "  return {",
      "    Sum: Sum,",
      "    Shown: Shown",
      "  };",
      "})();",
      "")));
  }

  /// <summary>A module without a public function exports nothing, in every module format.</summary>
  [Test]
  public void ModuleWithoutPublicFunctions_ExportsNothing() {
    const string source = "private static void A() { }";
    Assert.That(Emit(source, JavaScriptProfile.Parse("es2022", "esm")), Does.EndWith("\n// A(): void\nfunction A() {\n}\n"));
    Assert.That(Emit(source, JavaScriptProfile.Parse("es2022", "cjs")), Does.EndWith("\"use strict\";\n\n// A(): void\nfunction A() {\n}\n"));
    Assert.That(Emit(source, JavaScriptProfile.Parse("es2022", "iife", "G")),
      Does.EndWith("var G = (function () {\n  \"use strict\";\n\n  // A(): void\n  function A() {\n  }\n\n  return {};\n})();\n"));
  }

  /// <summary>A name the module format needs itself is renamed like a reserved word: exports in CommonJS, and there only.</summary>
  [Test]
  public void NameOfTheModuleFormat_GetsADollarSign() {
    const string source = "public static int exports(int globalThis) => globalThis; public static int F(int a) => exports(a);";
    var commonJs = Emit(source, JavaScriptProfile.Parse("es2015", "cjs"));
    Assert.That(commonJs, Does.Contain("function exports$(globalThis$) {\n  return globalThis$;\n}").And.Contain("return exports$(a);").And.Contain("exports.exports$ = exports$;\nexports.F = F;\n"));
    Assert.That(Emit(source, _es2015), Does.Contain("export function exports(globalThis$) {").And.Contain("return exports(a);"));
    Assert.That(Emit(source, JavaScriptProfile.Parse("es2015", "iife", "exports")), Does.Contain("var exports = (function () {").And.Contain("    exports: exports,\n    F: F\n"));
  }

  /// <summary>Each 64-bit operator as the call of the helper that computes it on pairs of halves.</summary>
  [TestCase("long", "a + b", "$add64(a, b)")]
  [TestCase("long", "a - b", "$sub64(a, b)")]
  [TestCase("long", "a * b", "$mul64(a, b)")]
  [TestCase("long", "a / b", "$div64(a, b)")]
  [TestCase("long", "a % b", "$rem64(a, b)")]
  [TestCase("long", "a & b", "$and64(a, b)")]
  [TestCase("long", "a | b", "$or64(a, b)")]
  [TestCase("long", "a ^ b", "$xor64(a, b)")]
  [TestCase("long", "a << 3", "$shl64(a, 3)")]
  [TestCase("long", "a << 67", "$shl64(a, 3)")]
  [TestCase("long", "a >> 3", "$sar64(a, 3)")]
  [TestCase("long", "a >>> 3", "$shr64(a, 3)")]
  [TestCase("long", "-a", "$neg64(a)")]
  [TestCase("long", "~a", "$not64(a)")]
  [TestCase("long", "a - -5", "$sub64(a, { hi: 4294967295, lo: 4294967291 })")]
  [TestCase("long", "(a * b) + 1", "$add64($mul64(a, b), { hi: 0, lo: 1 })")]
  [TestCase("ulong", "a + b", "$add64(a, b)")]
  [TestCase("ulong", "a - b", "$sub64(a, b)")]
  [TestCase("ulong", "a * b", "$mul64(a, b)")]
  [TestCase("ulong", "a / b", "$udiv64(a, b)")]
  [TestCase("ulong", "a % b", "$urem64(a, b)")]
  [TestCase("ulong", "a & b", "$and64(a, b)")]
  [TestCase("ulong", "a << 3", "$shl64(a, 3)")]
  [TestCase("ulong", "a >> 3", "$shr64(a, 3)")]
  [TestCase("ulong", "a >>> 3", "$shr64(a, 3)")]
  [TestCase("ulong", "~a", "$not64(a)")]
  [TestCase("ulong", "a * 0x100000001B3UL + 1UL", "$add64($mul64(a, { hi: 256, lo: 435 }), { hi: 0, lo: 1 })")]
  [TestCase("long", "checked(a + b)", "$addck64s(a, b)")]
  [TestCase("long", "checked(a - b)", "$subck64s(a, b)")]
  [TestCase("long", "checked(a * b)", "$mulck64s(a, b)")]
  [TestCase("long", "checked(-a)", "$subck64s({ hi: 0, lo: 0 }, a)")]
  [TestCase("ulong", "checked(a + b)", "$addck64u(a, b)")]
  [TestCase("ulong", "checked(a - b)", "$subck64u(a, b)")]
  [TestCase("ulong", "checked(a * b)", "$mulck64u(a, b)")]
  [TestCase("long", "a > b ? a : b", "($scmp64(a, b) > 0) ? a : b")]
  public void HalvesArithmetic_IsWrittenAsHelperCalls(string type, string expression, string expected) {
    Assert.That(Body($"public static {type} F({type} a, {type} b) => {expression};", _es2017), Is.EqualTo(new[] { $"return {expected};" }));
    Assert.That(Body($"public static {type} F({type} a, {type} b) => {expression};", _es5), Is.EqualTo(new[] { $"return {expected};" }));
  }

  /// <summary>A shift by a count that is not a constant leaves the masking to the helper; an order is the sign of a comparison.</summary>
  [TestCase("long", "a << n", "$shl64(a, n)")]
  [TestCase("long", "a >> (n + 1)", "$sar64(a, (n + 1) | 0)")]
  [TestCase("ulong", "a >>> n", "$shr64(a, n)")]
  [TestCase("ulong", "a == a", "$eq64(a, a)")]
  [TestCase("long", "a != a", "!$eq64(a, a)")]
  [TestCase("long", "a < a", "$scmp64(a, a) < 0")]
  [TestCase("long", "a <= a", "$scmp64(a, a) <= 0")]
  [TestCase("ulong", "a > a", "$ucmp64(a, a) > 0")]
  [TestCase("ulong", "a >= a", "$ucmp64(a, a) >= 0")]
  [TestCase("ulong", "a != a && a < a", "(!$eq64(a, a)) && ($ucmp64(a, a) < 0)")]
  public void HalvesShiftAndComparison_AreWritten(string type, string expression, string expected) {
    var returns = expression.Contains('=') || expression.Contains('<') && !expression.Contains("<<") || expression.Contains("> a") ? "bool" : type;
    Assert.That(Body($"public static {returns} F({type} a, int n) => {expression};", _es2015), Is.EqualTo(new[] { $"return {expected};" }));
  }

  /// <summary>Each conversion from, to and between pairs of halves.</summary>
  [TestCase("long", "int", "a", "$sx64(a)")]
  [TestCase("long", "sbyte", "a", "$sx64(a)")]
  [TestCase("ulong", "uint", "a", "{ hi: 0, lo: a }")]
  [TestCase("ulong", "char", "a", "{ hi: 0, lo: a }")]
  [TestCase("long", "uint", "a", "{ hi: 0, lo: a }")]
  [TestCase("ulong", "int", "(ulong)a", "$sx64(a)")]
  [TestCase("long", "ulong", "(long)a", "a")]
  [TestCase("ulong", "long", "(ulong)a", "a")]
  [TestCase("ulong", "long", "(ulong)(a + a)", "$add64(a, a)")]
  [TestCase("int", "long", "(int)a", "a.lo | 0")]
  [TestCase("uint", "long", "(uint)a", "a.lo")]
  [TestCase("uint", "ulong", "(uint)(a + a)", "$add64(a, a).lo")]
  [TestCase("byte", "ulong", "(byte)a", "a.lo & 0xFF")]
