  /// <summary>A step of a pair of halves: by the helper that adds or subtracts, wrapping around or trapping.</summary>
  [TestCase("long", "++a", "a = $add64(a, { hi: 0, lo: 1 })")]
  [TestCase("ulong", "--a", "a = $sub64(a, { hi: 0, lo: 1 })")]
  [TestCase("long", "checked(++a)", "a = $addck64s(a, { hi: 0, lo: 1 })")]
  [TestCase("long", "checked(--a)", "a = $subck64s(a, { hi: 0, lo: 1 })")]
  [TestCase("ulong", "checked(++a)", "a = $addck64u(a, { hi: 0, lo: 1 })")]
  [TestCase("ulong", "checked(--a)", "a = $subck64u(a, { hi: 0, lo: 1 })")]
  public void HalvesPrefixStep_IsWritten(string type, string expression, string expected)
    => Assert.That(Body($"public static {type} F({type} a) => {expression};", _es2017), Is.EqualTo(new[] { $"return {expected};" }));

  /// <summary>The variable that keeps the old value of a postfix step is declared with the keyword of the level.</summary>
  [Test]
  public void HalvesPostfixStep_IsWritten() {
    const string source = "public static ulong F(ulong a) => a--;";
    Assert.That(Body(source, _es2017), Is.EqualTo(new[] { "let $p;", "return ($p = a, a = $sub64($p, { hi: 0, lo: 1 }), $p);" }));
    Assert.That(Body(source, _es5), Is.EqualTo(new[] { "var $p;", "return ($p = a, a = $sub64($p, { hi: 0, lo: 1 }), $p);" }));
    Assert.That(Body(source, _es2020), Is.EqualTo(new[] { "let $p;", "return ($p = a, a = BigInt.asUintN(64, $p - 1n), $p);" }));
  }

  /// <summary>
  /// The step of an array element by the storage of the array: a typed array wraps by itself, a
  /// plain array of integers is told its width and signedness, one of binary32 numbers is rounded,
  /// and one of pairs of halves goes through their arithmetic.
  /// </summary>
  [TestCase("int", "x[i]++", "es2017", "$step(x, i, 1, true)")]
  [TestCase("int", "x[i]++", "es5", "$stepi(x, i, 1, true, 0, true)")]
  [TestCase("uint", "--x[i]", "es5", "$stepi(x, i, -1, false, 0, false)")]
  [TestCase("sbyte", "x[0]--", "es5", "$stepi(x, 0, -1, true, 24, true)")]
  [TestCase("byte", "++x[0]", "es5", "$stepi(x, 0, 1, false, 24, false)")]
  [TestCase("short", "++x[0]", "es5", "$stepi(x, 0, 1, false, 16, true)")]
  [TestCase("char", "x[0]--", "es5", "$stepi(x, 0, -1, true, 16, false)")]
  [TestCase("float", "x[0]++", "es5", "$stepf(x, 0, 1, true)")]
  [TestCase("float", "x[0]++", "es2015", "$step(x, 0, 1, true)")]
  [TestCase("double", "--x[0]", "es5", "$step(x, 0, -1, false)")]
  [TestCase("sbyte", "checked(++x[0])", "es5", "$stepck(x, 0, 1, false, -128, 127)")]
  [TestCase("long", "--x[i + 1]", "es2017", "$step64(x, (i + 1) | 0, false, false)")]
  [TestCase("long", "x[i]++", "es5", "$step64(x, i, true, true)")]
  [TestCase("long", "checked(++x[0])", "es2015", "$stepck64s(x, 0, true, false)")]
  [TestCase("ulong", "checked(x[i]--)", "es2017", "$stepck64u(x, i, false, true)")]
  [TestCase("long", "--x[i + 1]", "es2020", "$step(x, (i + 1) | 0, -1n, false)")]
  [TestCase("ulong", "checked(x[i]--)", "es2020", "$stepck(x, i, -1n, true, 0n, 18446744073709551615n)")]
  public void ElementStep_FollowsTheStorageOfTheArray(string type, string expression, string level, string expected)
    => Assert.That(Body($"public static {type} F({type}[] x, int i) => {expression};", JavaScriptProfile.Parse(level)), Is.EqualTo(new[] { $"return {expected};" }));

  /// <summary>With typed arrays an ECMAScript 5 engine stores into them as any later level does.</summary>
  [Test]
  public void ElementStep_WithTypedArraysAtEcmaScript5_IsThatOfTheTypedArray() {
    Assert.That(Body("public static byte F(byte[] x) => ++x[0];", _es5Typed), Is.EqualTo(new[] { "return $step(x, 0, 1, false);" }));
    Assert.That(Body("public static float F(float[] x) => ++x[0];", _es5Typed), Is.EqualTo(new[] { "return $step(x, 0, 1, false);" }));
    Assert.That(Body("public static long F(long[] x) => ++x[0];", _es5Typed), Is.EqualTo(new[] { "return $step64(x, 0, true, false);" }));
  }

  /// <summary>A switch over a pair of halves compares the text of the two halves, which a case can compare.</summary>
  [Test]
  public void SwitchOverHalves_ComparesTheirText() {
    const string source = "public static int F(long b, ulong c) { switch (b) { case 5: return 1; case long.MinValue: case -1: return 2; } switch (c) { case ulong.MaxValue: return 3; default: return 4; } }";
    Assert.That(Body(source, _es2017), Is.EqualTo(new[] {
      "switch ($key64(b)) {", "case \"0:5\": {", "return 1;", "}", "case \"2147483648:0\":", "case \"4294967295:4294967295\": {", "return 2;", "}", "}",
      "switch ($key64(c)) {", "case \"4294967295:4294967295\": {", "return 3;", "}", "default: {", "return 4;", "}", "}"
    }));
    Assert.That(Body(source, _es2020), Does.Contain("switch (b) {").And.Contain("case -9223372036854775808n:").And.Contain("case 18446744073709551615n: {"));
  }

  /// <summary>Arrays where the level has no typed array for the element: plain arrays, created, filled and copied by helpers.</summary>
  [Test]
  public void ArrayOperations_OnPlainArrays_AreWritten() {
    const string source = "public static long[] G(long[] a) => a; "
      + "public static int[] F(int[] a, long[] b, int n) { System.Array.Copy(a, n, a, 0, n + 1); System.Array.Copy(b, n, b, 0, 1); System.Array.Fill(a, n); System.Array.Fill(b, 7); "
      + "System.Array.Clear(a); System.Array.Clear(G(b)); long[] c = { n, 1 }; ulong[] d = []; float[] e = new float[n]; ulong[] f = new ulong[2]; return new[] { n, c.Length + d.Length + e.Length + f.Length }; }";
    Assert.That(Body(source, _es2017), Is.EqualTo(new[] {
      "$copy(a, n, a, 0, (n + 1) | 0);",
      "$copya(b, n, b, 0, 1);",
      "a.fill(n);",
      "b.fill({ hi: 0, lo: 7 });",
      "a.fill(0);",
      "G(b).fill({ hi: 0, lo: 0 });",
      "let c = [$sx64(n), { hi: 0, lo: 1 }];",
      "let d = [];",
      "let e = new Float32Array($len(n));",
      "let f = $new($len(2), { hi: 0, lo: 0 });",
      "return new Int32Array([n, (((((c.length + d.length) | 0) + e.length) | 0) + f.length) | 0]);"
    }));
    Assert.That(Body(source, _es5), Is.EqualTo(new[] {
      "$copya(a, n, a, 0, (n + 1) | 0);",
      "$copya(b, n, b, 0, 1);",
      "$fill(a, n);",
      "$fill(b, { hi: 0, lo: 7 });",
      "$fill(a, 0);",
      "$fill(G(b), { hi: 0, lo: 0 });",
      "var c = [$sx64(n), { hi: 0, lo: 1 }];",
      "var d = [];",
      "var e = $new($len(n), 0);",
      "var f = $new($len(2), { hi: 0, lo: 0 });",
      "return [n, (((((c.length + d.length) | 0) + e.length) | 0) + f.length) | 0];"
    }));
    Assert.That(Body(source, _es5Typed).Take(6).Concat(Body(source, _es5Typed).Skip(8)), Is.EqualTo(new[] {
      "$copy(a, n, a, 0, (n + 1) | 0);",
      "$copya(b, n, b, 0, 1);",
      "$fill(a, n);",
      "$fill(b, { hi: 0, lo: 7 });",
      "$fill(a, 0);",
      "$fill(G(b), { hi: 0, lo: 0 });",
      "var e = new Float32Array($len(n));",
      "var f = $new($len(2), { hi: 0, lo: 0 });",
      "return new Int32Array([n, (((((c.length + d.length) | 0) + e.length) | 0) + f.length) | 0]);"
    }));
  }

  /// <summary>The constants of a module with the keyword of the level, a table as the array the level has for it.</summary>
  [Test]
  public void Constants_FollowTheLevel() {
    const string source = "private const int K = 2; static readonly uint[] T = { 1, 2 }; static readonly long[] L = { -1, long.MaxValue }; static readonly ulong M = 1UL << 40; "
      + "static readonly byte[] N = { 1, 2, 3, 4, 5, 6, 7, 8, 9 }; public static double F(int i) => T[i] + L.Length + K + N[0] + (double)M;";
    Assert.That(Emit(source, _es2017), Does.Contain(string.Join('\n',
      "const K = 2;",
      "const T = new Uint32Array([1, 2]);",
      "const L = [{ hi: 4294967295, lo: 4294967295 }, { hi: 2147483647, lo: 4294967295 }];",
      "const M = { hi: 256, lo: 0 };",
      "const N = new Uint8Array([",
      "  1, 2, 3, 4, 5, 6, 7, 8,",
      "  9",
      "]);",
      "")));
    Assert.That(Emit(source, _es5), Does.Contain(string.Join('\n',
      "var K = 2;",
      "var T = [1, 2];",
      "var L = [{ hi: 4294967295, lo: 4294967295 }, { hi: 2147483647, lo: 4294967295 }];",
      "var M = { hi: 256, lo: 0 };",
      "var N = [",
      "  1, 2, 3, 4, 5, 6, 7, 8,",
      "  9",
      "];",
      "")));
    Assert.That(Emit(source, _es5Typed), Does.Contain("var T = new Uint32Array([1, 2]);\nvar L = [{ hi: 4294967295, lo: 4294967295 }, { hi: 2147483647, lo: 4294967295 }];"));
    Assert.That(Emit(source, _es2020), Does.Contain("const L = new BigInt64Array([-1n, 9223372036854775807n]);\nconst M = 1099511627776n;"));
  }

  /// <summary>
  /// Above every function: what crosses its boundary. Where a 64-bit integer is a pair of halves
  /// the header of the function says so and the header of the file says what such a pair is.
  /// </summary>
  [Test]
  public void Function_StatesItsBoundaryInTheTermsOfTheProfile() {
    const string source = "public static ulong F(long a, bool b, char c, short[] d, ulong[] e) => 1; public static float H(double a, float[] b) => 1; private static void G() { }";
    const string note = "// A 64-bit integer is an object { hi, lo }: its upper and its lower 32 bits, each as an unsigned number.\n";
    var modern = Emit(source, _es2017);
    Assert.That(modern, Does.StartWith("// Snippet: generated by polypiler. Change the source, not this file.\n// JavaScript profile: es2017, esm.\n" + note + "\n// F("));
    Assert.That(modern, Does.Contain("\n// F(a: { hi, lo }, b: boolean, c: number, d: Int16Array, e: Array<{ hi, lo }>): { hi, lo }\nexport function F(a, b, c, d, e) {\n  return { hi: 0, lo: 1 };\n}\n"));
    Assert.That(modern, Does.Contain("\n// H(a: number, b: Float32Array): number\nexport function H(a, b) {\n  return 1;\n}\n"));

    var old = Emit(source, _es5);
    Assert.That(old, Does.StartWith("// Snippet: generated by polypiler. Change the source, not this file.\n// JavaScript profile: es5, cjs.\n" + note + "\"use strict\";\n\n// F("));
    Assert.That(old, Does.Contain("\n// F(a: { hi, lo }, b: boolean, c: number, d: Array<number>, e: Array<{ hi, lo }>): { hi, lo }\nfunction F(a, b, c, d, e) {"));
    Assert.That(old, Does.Contain("\n// H(a: number, b: Array<number>): number\nfunction H(a, b) {"));
    Assert.That(Emit(source, _es5Typed), Does.Contain("\n// F(a: { hi, lo }, b: boolean, c: number, d: Int16Array, e: Array<{ hi, lo }>): { hi, lo }\n"));

    Assert.That(Emit(source, _es2020), Does.Not.Contain(note).And.Contain("// F(a: bigint, b: boolean, c: number, d: Int16Array, e: BigUint64Array): bigint"));
    Assert.That(Emit("public static int F(int a) { long b = a; return (int)(b + b); }", _es2017), Does.Not.Contain(note), "no pair crosses the boundary");
  }

  /// <summary>What ECMAScript 2015 added to Math, and what stands in for it at ECMAScript 5.</summary>
  [TestCase("int", "int", "a * a", "Math.imul(a, a)", "$imul(a, a)")]
  [TestCase("uint", "uint", "a * a", "Math.imul(a, a) >>> 0", "$imul(a, a) >>> 0")]
  [TestCase("int", "uint", "System.Numerics.BitOperations.LeadingZeroCount(a)", "Math.clz32(a)", "$clz32(a)")]
  [TestCase("int", "uint", "System.Numerics.BitOperations.Log2(a)", "31 - Math.clz32(a | 1)", "31 - $clz32(a | 1)")]
  [TestCase("float", "float", "a + a", "Math.fround(a + a)", "$fround(a + a)")]
  [TestCase("float", "float", "System.MathF.Sqrt(a)", "Math.fround(Math.sqrt(a))", "$fround(Math.sqrt(a))")]
  [TestCase("float", "int", "a", "Math.fround(a)", "$fround(a)")]
  [TestCase("float", "float", "++a", "a = Math.fround(a + 1)", "a = $fround(a + 1)")]
  [TestCase("double", "double", "System.Math.Truncate(a)", "Math.trunc(a)", "$trunc(a)")]
  [TestCase("int", "int", "System.Math.Sign(a)", "Math.sign(a)", "$sign(a)")]
  [TestCase("double", "double", "System.Math.Floor(a) + System.Math.Ceiling(a) + System.Math.Abs(a) + System.Math.Sqrt(a) + System.Math.Min(a, a) + System.Math.Max(a, a)",
    "((((Math.floor(a) + Math.ceil(a)) + Math.abs(a)) + Math.sqrt(a)) + Math.min(a, a)) + Math.max(a, a)",
    "((((Math.floor(a) + Math.ceil(a)) + Math.abs(a)) + Math.sqrt(a)) + Math.min(a, a)) + Math.max(a, a)")]
  public void MathOfEcmaScript2015_IsReplacedBelow(string returns, string type, string expression, string native, string replacement) {
    var source = $"public static {returns} F({type} a) => {expression};";
    Assert.That(Body(source, _es2015), Is.EqualTo(new[] { $"return {native};" }));
    Assert.That(Body(source, _es5), Is.EqualTo(new[] { $"return {replacement};" }));
    Assert.That(Body(source, _es5Typed), Is.EqualTo(new[] { $"return {replacement};" }));
  }

  /// <summary>The helpers bring the helpers they call, each written for the level: the replacement of Math.imul inside the bit count.</summary>
  [Test]
  public void Helpers_AreWrittenForTheLevel() {
    const string source = "public static int F(uint a, ulong b, float f) => System.Numerics.BitOperations.PopCount(a) + System.Numerics.BitOperations.TrailingZeroCount(b) + (int)f + (int)(f * f);";
    var old = Emit(source, _es5);
    Assert.That(Helpers(old), Is.EqualTo(new[] { "imul", "clz32", "fround", "trunc", "f2i", "pop", "ctz", "ctz64" }));
    Assert.That(old, Does.Contain("return $imul((value + (value >>> 4)) & 0x0F0F0F0F, 0x01010101) >>> 24;")
      .And.Contain("return value === 0 ? 32 : 31 - $clz32(value & -value);")
      .And.Contain("return value.lo !== 0 ? $ctz(value.lo) : 32 + $ctz(value.hi);")
      .And.Contain("return value <= low ? low : value >= high ? high : $trunc(value) + 0;")
      .And.Contain("  var whole = Math.floor(rest);\n"));

    var typed = Emit(source, _es5Typed);
    Assert.That(Helpers(typed), Is.EqualTo(Helpers(old)));
    Assert.That(typed, Does.Contain("var $f32a = new Float32Array(1);\n\nfunction $fround(value) {\n  $f32a[0] = value;\n  return $f32a[0];\n}\n"));

    var modern = Emit(source, _es2017);
    Assert.That(Helpers(modern), Is.EqualTo(new[] { "f2i", "pop", "ctz", "ctz64" }));
    Assert.That(modern, Does.Contain("return Math.imul((value + (value >>> 4)) & 0x0F0F0F0F, 0x01010101) >>> 24;")
      .And.Contain("return value === 0 ? 32 : 31 - Math.clz32(value & -value);")
      .And.Contain("return value.lo !== 0 ? $ctz(value.lo) : 32 + $ctz(value.hi);"));

    Assert.That(Emit(source, _es2020), Does.Contain("  const low = Number(value & 0xFFFFFFFFn);\n  return low !== 0 ? $ctz(low) : 32 + $ctz(Number(value >> 32n));"));
  }

  /// <summary>The helpers of the arithmetic on pairs of halves, in their order, each with what it calls.</summary>
  [Test]
  public void HalvesHelpers_AreListedOnceWithWhatTheyNeed() {
    var text = Emit(
      "public static long F(long a, ulong u, int n, double d, float f, long[] x, ulong[] y) => checked(a / a % a + (long)(u / u % u) * a - (a << n)) + (a >> n) + (long)(u >> n) + (~a & a | a ^ a) "
      + "+ (a == a ? 1 : 0) + (u < u ? 1 : 0) + (a < a ? 1 : 0) + System.Math.Abs(a) + System.Math.Min(a, a) + System.Math.Max(a, a) + (long)System.Math.Min(u, u) + (long)System.Math.Max(u, u) "
      + "+ System.Math.Sign(a) + (long)System.Numerics.BitOperations.RotateLeft(u, n) + (long)System.Numerics.BitOperations.RotateRight(u, n) + System.Numerics.BitOperations.PopCount(u) "
      + "+ System.Numerics.BitOperations.LeadingZeroCount(u) + System.Numerics.BitOperations.TrailingZeroCount(u) + System.BitConverter.DoubleToInt64Bits(d) + (long)System.BitConverter.Int64BitsToDouble(a) "
      + "+ (long)d + checked((long)d) + (long)(float)a + (long)(float)u + (long)(double)a + (long)(double)u + checked((int)a) + (long)checked(u + u) + (long)checked(u - u) + (long)checked(u * u) + (long)checked((uint)u) "
      + "+ x[0]++ + checked(x[0]--) + (long)checked(++y[0]) + (-a) + n;",
      _es2017);
    Assert.That(Helpers(text), Is.EqualTo(new[] {
      "add64", "sub64", "neg64", "not64", "and64", "or64", "xor64", "shl64", "shr64", "sar64", "eq64", "ucmp64", "scmp64", "mulw", "mag64", "udm64",
      "div64", "rem64", "udiv64", "urem64", "addck64s", "addck64u", "subck64s", "subck64u", "mulck64s", "mulck64u", "ck64s", "ck64u", "sx64", "ul2d", "l2d", "d2l",
      "f2l", "f2lc", "ul2f", "l2f", "abs64", "smin64", "umin64", "smax64", "umax64", "sign64", "rotl64", "rotr64", "pop", "pop64", "clz64", "ctz", "ctz64",
      "bits64", "float64", "step64", "stepck64s", "stepck64u"
    }));
    Assert.That(text, Does.Contain("const $view = new DataView(new ArrayBuffer(8));")
      .And.Contain("  return { hi: $view.getUint32(0), lo: $view.getUint32(4) };")
      .And.Contain("  $view.setUint32(0, value.hi);\n  $view.setUint32(4, value.lo);\n  return $view.getFloat64(0);")
      .And.Contain("  if (n === 0) throw new RangeError(\"divide by zero\");")
      .And.Contain("  if (a.hi === 2147483648 && a.lo === 0 && b.hi === 4294967295 && b.lo === 4294967295) throw new RangeError(\"integer overflow\");")
      .And.Contain("  return Math.fround((value.hi >>> 11) * 4294967296 + lo) * 2048;")
      .And.Not.Contain("BigInt").And.Not.Contain("var "));
    Assert.That(text.Split('\n').Count(line => line.StartsWith("function $", StringComparison.Ordinal)), Is.EqualTo(Helpers(text).Distinct().Count()));
  }

  /// <summary>Without a DataView the bits of a floating-point number are taken apart and put together by arithmetic.</summary>
  [Test]
  public void BitsOfAFloat_AreComputedWhereThereIsNoDataView() {
    const string source = "public static long F(double d, float f, long l, int i) => System.BitConverter.DoubleToInt64Bits(d) + System.BitConverter.SingleToInt32Bits(f) "
      + "+ (long)System.BitConverter.Int64BitsToDouble(l) + (long)System.BitConverter.Int32BitsToSingle(i);";
    var plain = Emit(source, _es5);
    Assert.That(plain, Does.Not.Contain("$view").And.Not.Contain("DataView"));
    Assert.That(plain, Does.Contain("function $bits64(value) {\n  if (value !== value) return { hi: 2146959360, lo: 0 };")
      .And.Contain("function $bits32(value) {\n  if (value !== value) return 2143289344;")
      .And.Contain("function $float64(value) {\n  var exponent = (value.hi >>> 20) & 2047;")
      .And.Contain("function $float32(value) {\n  var exponent = (value >>> 23) & 255;"));

    var typed = Emit(source, _es5Typed);
    Assert.That(typed, Does.Contain("var $view = new DataView(new ArrayBuffer(8));")
      .And.Contain("function $bits32(value) {\n  $view.setFloat32(0, value);\n  return $view.getInt32(0);\n}")
      .And.Contain("function $float32(value) {\n  $view.setInt32(0, value);\n  return $view.getFloat32(0);\n}")
      .And.Contain("  return { hi: $view.getUint32(0), lo: $view.getUint32(4) };"));
    Assert.That(Emit(source, _es2020), Does.Contain("const $view = new DataView(new ArrayBuffer(8));").And.Contain("  return $view.getBigInt64(0);").And.Contain("  $view.setBigInt64(0, value);"));
  }

  /// <summary>
  /// Test design 3: every entry of the table that the emitter writes and that has a replacement is
  /// written natively by the first profile that has it and as its replacement by the last one that
  /// has not. A new entry needs a case here before this test passes.
  /// </summary>
  [Test]
  public void EveryReplaceableCapability_IsNativeAtItsLevelAndReplacedBelow() {
    const string bits = "public static long F(double d, float f, long l, int i) => System.BitConverter.DoubleToInt64Bits(d) + System.BitConverter.SingleToInt32Bits(f) "
      + "+ (long)System.BitConverter.Int64BitsToDouble(l) + (long)System.BitConverter.Int32BitsToSingle(i);";
    string Array(string element) => $"public static int F(int n) => new {element}[n].Length;";
    string Read(string name, string type)
      => $"public static {type} F(byte[] a) {{ System.ReadOnlySpan<byte> s = a; return System.Buffers.Binary.BinaryPrimitives.Read{name}LittleEndian(s.Slice(1)); }}";
    string Write(string name, string type)
      => $"public static byte[] F(byte[] a, {type} v) {{ System.Span<byte> s = a; System.Buffers.Binary.BinaryPrimitives.Write{name}LittleEndian(s, v); return a; }}";
    var cases = new Dictionary<string, (string Source, string Native, string Replacement)> {
      ["let"] = ("public static int F(int a) { int b = a; return b; }", "let b = a;", "var b = a;"),
      ["const"] = ("const int K = 2; public static int F() => K;", "const K = 2;", "var K = 2;"),
      ["export"] = ("public static int F() => 1;", "export function F() {", "exports.F = F;"),
      ["Math.imul"] = ("public static int F(int a) => a * a;", "Math.imul(a, a)", "$imul(a, a)"),
      ["Math.log2"] = ("public static float F(float a) => System.MathF.Log2(a);", "Math.log2(", "Float"),
      ["Math.log10"] = ("public static float F(float a) => System.MathF.Log10(a);", "Math.log10(", "Float"),
      ["Math.sinh"] = ("public static float F(float a) => System.MathF.Sinh(a);", "Math.sinh(", "Float"),
      ["Math.cosh"] = ("public static float F(float a) => System.MathF.Cosh(a);", "Math.cosh(", "Float"),
      ["Math.tanh"] = ("public static float F(float a) => System.MathF.Tanh(a);", "Math.tanh(", "Float"),
      ["Math.cbrt"] = ("public static float F(float a) => System.MathF.Cbrt(a);", "Math.cbrt(", "Float"),
      ["Math.hypot"] = ("public static float F(float a) => System.Single.Hypot(a, a);", "Math.hypot(", "Float"),
      ["Math.clz32"] = ("public static int F(uint a) => System.Numerics.BitOperations.LeadingZeroCount(a);", "Math.clz32(a)", "$clz32(a)"),
      ["Math.fround"] = ("public static float F(float a) => a + a;", "Math.fround(a + a)", "$fround(a + a)"),
      ["Math.trunc"] = ("public static double F(double a) => System.Math.Truncate(a);", "Math.trunc(a)", "$trunc(a)"),
      ["Math.sign"] = ("public static int F(int a) => System.Math.Sign(a);", "Math.sign(a)", "$sign(a)"),
      ["Int8Array"] = (Array("sbyte"), "new Int8Array($len(n))", "$new($len(n), 0)"),
      ["Uint8Array"] = (Array("byte"), "new Uint8Array($len(n))", "$new($len(n), 0)"),
      ["Int16Array"] = (Array("short"), "new Int16Array($len(n))", "$new($len(n), 0)"),
      ["Uint16Array"] = (Array("ushort"), "new Uint16Array($len(n))", "$new($len(n), 0)"),
      ["Int32Array"] = (Array("int"), "new Int32Array($len(n))", "$new($len(n), 0)"),
      ["Uint32Array"] = (Array("uint"), "new Uint32Array($len(n))", "$new($len(n), 0)"),
      ["Float32Array"] = (Array("float"), "new Float32Array($len(n))", "$new($len(n), 0)"),
      ["Float64Array"] = (Array("double"), "new Float64Array($len(n))", "$new($len(n), 0)"),
      ["ArrayBuffer"] = (bits, "new ArrayBuffer(8)", "if (value !== value) return { hi: 2146959360, lo: 0 };"),
      ["DataView"] = (bits, "new DataView(", "if (value !== value) return { hi: 2146959360, lo: 0 };"),
      [".set"] = ("public static void F(int[] a) { System.Array.Copy(a, 0, a, 1, 2); }", "target.set(", "$copya(a, 0, a, 1, 2)"),
      [".subarray"] = ("public static void F(int[] a) { System.Array.Copy(a, 0, a, 1, 2); }", "source.subarray(from, from + length)", "$copya(a, 0, a, 1, 2)"),
      [".setFloat64"] = (bits, "$view.setFloat64(0, value);", "function $bits64(value) {\n  if (value !== value)"),
      [".getFloat64"] = (bits, "return $view.getFloat64(0);", "function $float64(value) {\n  var exponent"),
      [".setFloat32"] = (bits, "$view.setFloat32(0, value);", "function $bits32(value) {\n  if (value !== value)"),
      [".getFloat32"] = (bits, "return $view.getFloat32(0);", "function $float32(value) {\n  var exponent"),
      [".setInt32"] = (bits, "$view.setInt32(0, value);", "function $float32(value) {\n  var exponent"),
      [".getInt32"] = (bits, "return $view.getInt32(0);", "function $bits32(value) {\n  if (value !== value)"),
      [".setUint32"] = (bits, "$view.setUint32(0, value.hi);", "function $float64(value) {\n  var exponent"),
      [".getUint32"] = (bits, "hi: $view.getUint32(0)", "function $bits64(value) {\n  if (value !== value)"),
      [".fill"] = ("public static void F(int[] a) { System.Array.Fill(a, 7); }", "a.fill(7)", "$fill(a, 7)"),
      ["shorthand property"] = ("public struct V { public double X; public V(double x) { X = x; } } public static V F(double X) => new V(X);", "return { X };", "return { X: X };"),
      ["BigInt"] = ("public static long F(int a) => a;", "BigInt(a)", "$sx64(a)"),
      ["BigInt.asIntN"] = ("public static long F(long a) => a + a;", "BigInt.asIntN(64, a + a)", "$add64(a, a)"),
      ["BigInt.asUintN"] = ("public static ulong F(ulong a) => a + a;", "BigInt.asUintN(64, a + a)", "$add64(a, a)"),
      ["BigInt64Array"] = (Array("long"), "new BigInt64Array($len(n))", "$new($len(n), { hi: 0, lo: 0 })"),
      ["BigUint64Array"] = (Array("ulong"), "new BigUint64Array($len(n))", "$new($len(n), { hi: 0, lo: 0 })"),
      [".getBigInt64"] = (bits, "return $view.getBigInt64(0);", "hi: $view.getUint32(0)"),
      [".setBigInt64"] = (bits, "$view.setBigInt64(0, value);", "$view.setUint32(0, value.hi);"),
      ["subarray as a view"] = ("public static int F(byte[] a) { System.Span<byte> s = System.MemoryExtensions.AsSpan(a, 1); return s.Length; }", "view.subarray(start, start + length)", "$vobj(a, 1)"),
      [".getInt16"] = (Read("Int16", "short"), ".getInt16(0, true)", "$vat("),
      [".getUint16"] = (Read("UInt16", "ushort"), ".getUint16(0, true)", "$vat("),
      [".setInt16"] = (Write("Int16", "short"), "\"setInt16\"", "$vat(s, 0, 2)"),
      [".setUint16"] = (Write("UInt16", "ushort"), "\"setUint16\"", "$vat(s, 0, 2)"),
      [".getBigUint64"] = (Read("UInt64", "ulong"), ".getBigUint64(0, true)", "$load64("),
      [".setBigUint64"] = (Write("UInt64", "ulong"), "\"setBigUint64\"", "$store64(")
    };
    // The methods of strings begin at levels this test does not compare; JavaScriptStringEmissionTests checks each at its first level and the one before.
    var replaceable = JavaScriptCapabilities.Standard.Entries
      .Where(entry => entry is { Emitted: true, Replacement: not null } && !Polypiler.Tests.String.JavaScriptStringEmissionTests.Methods.Contains(entry.Name)).ToList();
    Assert.That(cases.Keys, Is.EquivalentTo(replaceable.Select(entry => entry.Name)));
    foreach (var entry in replaceable) {
      var (source, native, replacement) = cases[entry.Name];
      // The pair of halves has two forms itself: a typed array of 32-bit halves needs the level that brought the
      // typed arrays, so what is native from ECMAScript 2020 is compared with ECMAScript 2017, the rest with ECMAScript 5.
      var first = entry.Since == 2020 ? _es2020 : entry.Name is ".setUint32" or ".getUint32" ? _es2017 : _es2015;
      var last = entry.Since == 2020 ? _es2017 : _es5;
      Assert.That(Emit(source, first), Does.Contain(native), $"{entry.Name} is native in {first}");
      Assert.That(Emit(source, last), Does.Not.Contain(native).And.Contain(replacement), $"{entry.Name} is replaced in {last}");
      if (entry.TypedArray)
        Assert.That(Emit(source, _es5Typed), Does.Contain(native), $"{entry.Name} is native in {_es5Typed}");
    }
  }

  /// <summary>What the table lists as never emitted is in no file of any fixture, at any level.</summary>
  [Test, Category("Slow")]
  public void NeverEmittedCapabilities_AreInNoFile() {
    var never = JavaScriptCapabilities.Standard.Entries.Where(entry => !entry.Emitted).Select(entry => entry.Name).Where(name => name != "numeric separators").ToList();
    Assert.That(never, Has.Count.EqualTo(12));
    foreach (var fixture in PrototypeFixture.Names)
      foreach (var profile in new[] { _es5, _es2017, JavaScriptProfile.Default }) {
        var text = JavaScriptEmitter.Emit(PrototypeFixture.Imported(fixture), profile).Single().Content;
        Assert.That(never.Where(text.Contains), Is.Empty, $"{fixture} as {profile}");
        Assert.That(System.Text.RegularExpressions.Regex.IsMatch(text, @"\d_\d"), Is.False, $"{fixture} as {profile}");
      }
  }

  /// <summary>
  /// A <c>var</c> belongs to its function. A local that is declared while another one of its name
  /// is visible gets a name of its own, also against a name that only looks like such a one; where
  /// the other one is no longer visible the name is free again. A <c>let</c> declared while one of its
  /// name is visible would hide that one from its block, so it is renamed as well, to
  /// <c>&lt;name&gt;_&lt;k&gt;</c> with a <c>k</c> no other local of the function has (#1343). The
  /// frontend never shadows, so the module is built by hand.
  /// </summary>
  [Test]
  public void Var_GetsAHoistingSafeName() {
    var x = new IrLocal("x", IrType.I32);
    var inner = new IrLocal("x", IrType.U32);
    var innermost = new IrLocal("x", IrType.U8);
    var taken = new IrLocal("x$1", IrType.I32);
    var again = new IrLocal("x", IrType.U32);
    var body = new IrBlock([
      new IrDeclare(taken, new IrConst(IrType.I32, 7)),
      new IrBlock([
        new IrDeclare(inner, new IrConst(IrType.U32, 1)),
        new IrBlock([new IrDeclare(innermost, null), new IrAssign(innermost, new IrConst(IrType.U8, 2))]),
        new IrExprStmt(new IrStep(new IrLocalRef(inner), true, false, false)),
        new IrAssign(x, new IrConvert(IrType.I32, new IrLocalRef(inner), IrConversion.Wrap))
      ]),
      new IrBlock([new IrDeclare(again, new IrConst(IrType.U32, 3)), new IrAssign(again, new IrLocalRef(again))]),
      new IrReturn(new IrBinary(IrBinaryOp.Add, new IrLocalRef(x), new IrLocalRef(taken)))
    ]);
    var module = new IrModule("M", [new IrFunction("F", true, IrType.I32, [x], [taken, inner, innermost, again], body)]);
    Assert.That(IrVerifier.Verify(module), Is.Empty);

    string[] Lines(JavaScriptProfile profile) {
      var text = JavaScriptEmitter.Emit(module, profile).Single().Content;
      Assert.That(GeneratedJavaScript.Problems(text, profile), Is.Empty);
      return text.Split('\n').Select(line => line.Trim()).SkipWhile(line => !line.StartsWith("function F", StringComparison.Ordinal)).Skip(1).TakeWhile(line => line != "exports.F = F;").ToArray();
    }

    Assert.That(Lines(_es5), Is.EqualTo(new[] {
      "var x$1 = 7;", "{", "var x$2 = 1;", "{", "var x$3;", "x$3 = 2;", "}", "x$2 = (x$2 + 1) >>> 0;", "x = x$2 | 0;", "}",
      "{", "var x$2 = 3;", "x$2 = x$2;", "}", "return (x + x$1) | 0;", "}", ""
    }));
    Assert.That(Lines(JavaScriptProfile.Parse("es2015", "cjs")), Is.EqualTo(new[] {
      "let x$1 = 7;", "{", "let x_1 = 1;", "{", "let x_2;", "x_2 = 2;", "}", "x_1 = (x_1 + 1) >>> 0;", "x = x_1 | 0;", "}",
      "{", "let x_3 = 3;", "x_3 = x_3;", "}", "return (x + x$1) | 0;", "}", ""
    }));
    Assert.That(IrInterpreter.Call(module, "F", [5]), Is.EqualTo(9));
  }

  /// <summary>The temporaries of a for step and the variable of a postfix step are declared with the keyword of the level.</summary>
  [Test]
  public void ForStep_DeclaresItsTemporariesWithTheKeywordOfTheLevel() {
    var body = Body("public static void F(int[] c, int n) { for (int i = 0; i < n; c[i + 1] += 2, ++i) continue; for (int i = 0; i < n; i++) continue; }", _es5);
    Assert.That(body, Is.EqualTo(new[] {
      "{",
      "var i = 0;",
      "{",
      "var $t1;",
      "for (; i < n; $t1 = (i + 1) | 0, $set(c, $t1, ($get(c, $t1) + 2) | 0), i = (i + 1) | 0) {",
      "continue;",
      "}",
      "}",
      "}",
      "{",
      "var i = 0;",
      "for (; i < n; i = (i + 1) | 0) {",
      "continue;",
      "}",
      "}"
    }));
  }

  /// <summary>
  /// A pair of halves is an object literal, which at the start of a statement would be read as a
  /// block. The frontend never makes a constant a statement, so the module is built by hand.
  /// </summary>
  [Test]
  public void PairAsAStatement_IsInParentheses() {
    var module = new IrModule("M", [new IrFunction("F", true, IrType.Void, [], [], new IrBlock([new IrExprStmt(new IrConst(IrType.U64, 1)), new IrExprStmt(new IrConst(IrType.I32, 1))]))]);
    Assert.That(IrVerifier.Verify(module), Is.Empty);
    var text = JavaScriptEmitter.Emit(module, _es2017).Single().Content;
    Assert.That(text, Does.EndWith("export function F() {\n  ({ hi: 0, lo: 1 });\n  1;\n}\n"));
    Assert.That(GeneratedJavaScript.Problems(text, _es2017), Is.Empty);
    Assert.That(JavaScriptEmitter.Emit(module, _es2020).Single().Content, Does.EndWith("export function F() {\n  1n;\n  1;\n}\n"));
  }

  /// <summary>
  /// Test design 9: a construct that has neither a native form nor a replacement in the profile is
  /// reported by the name of the IR construct and the profile, once, and nothing is emitted. The
  /// standard table replaces everything, so the table here is one that does not.
  /// </summary>
  [TestCase("Math.imul", "es5", "public static int F(int a) => a * a;", "Multiply")]
  [TestCase("Math.trunc", "es5", "public static double F(double a) => System.Math.Truncate(a) + System.Math.Truncate(a);", "Truncate")]
  [TestCase("Math.fround", "es5", "public static float F(int a) => a;", "Convert")]
  [TestCase("let", "es5", "public static int F(int a) { int b = a; int c = b; return c; }", "Declare")]
  [TestCase("const", "es5", "const int K = 1; public static int F() => K;", "the module")]
  [TestCase("BigInt", "es2017", "public static void F() { long a = 1; a = -a; }", "Negate")]
  [TestCase("BigInt", "es2017", "public static long F(long a) => a;", "the function 'F'")]
  [TestCase("Float64Array", "es5", "public static int F() => new double[2].Length;", "NewArray")]
  [TestCase(".fill", "es5", "public static void F(int[] a) { System.Array.Clear(a); }", "ArrayClear")]
  public void ConstructWithoutAForm_IsReported(string capability, string level, string source, string construct) {
    var profile = JavaScriptProfile.Parse(level);
    var table = JavaScriptCapabilities.Standard.With(JavaScriptCapabilities.Standard[capability] with { Replacement = null });
    var module = Import(source);
    var message = $"'{construct}' cannot be expressed in JavaScript profile '{level}'";

    var problems = JavaScriptEmitter.Check(module, profile, table);
    Assert.That(problems.Select(problem => problem.ToString()), Has.Exactly(1).EqualTo($"error PLY1152: {message}"));
    Assert.That(problems.Select(problem => (problem.Code, problem.Severity)), Has.All.EqualTo((JavaScriptEmitter.Inexpressible, DiagnosticSeverity.Error)));
    Assert.That(problems.Select(problem => problem.Message), Is.Unique);
    Assert.That(() => JavaScriptEmitter.Emit(module, profile, table), Throws.ArgumentException.With.Message.Contains("The module 'Snippet' cannot be emitted: '").And.Message.Contains("cannot be expressed in JavaScript profile"));

    Assert.That(JavaScriptEmitter.Check(module, profile), Is.Empty, "the standard table has a replacement");
    Assert.That(JavaScriptEmitter.Check(module, JavaScriptProfile.Default, table), Is.Empty, "the level that has it needs no replacement");
    Assert.That(JavaScriptEmitter.Emit(module, JavaScriptProfile.Default, table).Single().Content, Is.EqualTo(JavaScriptEmitter.Emit(module).Single().Content));
  }

  /// <summary>
  /// The operations of ECMA-262 itself that the JavaScript frontend imports: <c>ToInt32</c>,
  /// <c>ToUint32</c> and <c>Math.round</c>. All three are in ECMAScript 5, so every profile writes
  /// them as they are. The frontend builds them from JavaScript, so the module is built by hand.
  /// </summary>
  private static IrModule EcmaScriptOperations() {
    var d = new IrLocal("d", IrType.F64);
    var f = new IrLocal("f", IrType.F32);
    IrFunction Function(string name, IrIntrinsicOp op, IrType type, IrLocal operand)
      => new(name, true, type, [operand], [], new IrBlock([new IrReturn(new IrIntrinsic(op, type, [new IrLocalRef(operand)]))]));
    return new IrModule("Ecma", [
      Function("ToInt32", IrIntrinsicOp.ToInt32, IrType.I32, d),
      Function("ToUint32", IrIntrinsicOp.ToUint32, IrType.U32, d),
      Function("Round", IrIntrinsicOp.RoundHalfUp, IrType.F64, d),
      Function("RoundSingle", IrIntrinsicOp.RoundHalfUp, IrType.F32, f)
    ], []);
  }

  [TestCaseSource(nameof(_profiles))]
  public void EcmaScriptOperations_AreWrittenAsTheyAreInEveryProfile(JavaScriptProfile profile) {
    var module = EcmaScriptOperations();
    Assert.That(IrVerifier.Verify(module), Is.Empty);
    Assert.That(JavaScriptEmitter.Check(module, profile), Is.Empty);
    var text = JavaScriptEmitter.Emit(module, profile).Single().Content;
    Assert.That(GeneratedJavaScript.Problems(text, profile), Is.Empty);
    Assert.That(text, Does.Contain("  return d | 0;\n").And.Contain("  return d >>> 0;\n").And.Contain("  return Math.round(d);\n").And.Contain("  return Math.round(f);\n"));
    Assert.That(Helpers(text), Is.Empty);
  }

  /// <summary>Each of the three is taken from its own entry of the table, so a table that lacks one refuses it with PLY1152.</summary>
  [TestCase("| 0", "ToInt32")]
  [TestCase(">>> 0", "ToUint32")]
  [TestCase("Math.round", "RoundHalfUp")]
  public void EcmaScriptOperation_WithoutAnEntryForItsLevel_IsReported(string capability, string construct) {
    var table = JavaScriptCapabilities.Standard.With(new(capability, 2015));
    var problems = JavaScriptEmitter.Check(EcmaScriptOperations(), _es5, table);
    Assert.That(problems.Select(problem => problem.ToString()), Is.EqualTo(new[] { $"error PLY1152: '{construct}' cannot be expressed in JavaScript profile 'es5'" }));
    Assert.That(JavaScriptEmitter.Check(EcmaScriptOperations(), _es2015, table), Is.Empty);
  }

  /// <summary>An ill-typed module is reported by the verifier's findings, whatever the profile, and not emitted.</summary>
  [Test]
  public void IllTypedModule_IsReportedAndNotEmitted() {
    var module = new IrModule("M", [new IrFunction("F", true, IrType.I32, [], [], new IrBlock([new IrReturn(new IrConst(IrType.Bool, 1))]))]);
    Assert.That(JavaScriptEmitter.Check(module, _es5).Select(problem => problem.Code), Is.EqualTo(new[] { IrVerifier.Code }));
    Assert.That(() => JavaScriptEmitter.Emit(module, _es5), Throws.ArgumentException.With.Message.Contains("The module 'M' cannot be emitted: ill-typed IR in 'F'"));
  }

  /// <summary>A table that lacks an entry the emitter asks for is a mistake of whoever made the table.</summary>
  [Test]
  public void TableWithoutAnEntry_IsAnError() {
    var module = Import("public static int F(int a) => a * a;");
    Assert.That(() => JavaScriptEmitter.Check(module, _es5, new JavaScriptCapabilities([])), Throws.ArgumentException.With.Message.Contains("The capability table has no entry '"));
  }

